import struct, os, json, sys, shutil

def read_tiff(path):
    with open(path,'rb') as f:
        d=f.read()
    if len(d)<8:
        raise ValueError("not tiff")
    endian=d[0:2]
    fmt='<'
    if endian==b'II':
        fmt='<'
    else:
        fmt='>'
    magic=struct.unpack(fmt+'H', d[2:4])[0]
    if magic!=42:
        raise ValueError("not tiff magic")
    off=struct.unpack(fmt+'I', d[4:8])[0]
    num=struct.unpack(fmt+'H', d[off:off+2])[0]
    tags={}
    for i in range(num):
        pos=off+2+i*12
        tag,typ,count,val=struct.unpack(fmt+'HHI4s', d[pos:pos+12])
        val_int=struct.unpack(fmt+'I', val)[0]
        # For SHORT count 1, value is in val_int low 2 bytes
        # For LONG count 1, value is val_int
        # For larger counts, data at offset val_int
        if typ==3 and count==1:
            actual=val_int & 0xFFFF
            tags[tag]=(typ,count,actual,None)
        elif typ==4 and count==1:
            tags[tag]=(typ,count,val_int,None)
        else:
            # need to read
            data_offset=val_int
            if typ==3:
                vals=struct.unpack(fmt+f'{count}H', d[data_offset:data_offset+count*2])
                tags[tag]=(typ,count,vals,data_offset)
            elif typ==4:
                vals=struct.unpack(fmt+f'{count}I', d[data_offset:data_offset+count*4])
                tags[tag]=(typ,count,vals,data_offset)
            elif typ==12:
                vals=struct.unpack(fmt+f'{count}d', d[data_offset:data_offset+count*8])
                tags[tag]=(typ,count,vals,data_offset)
            elif typ==2:
                s=d[data_offset:data_offset+count]
                tags[tag]=(typ,count,s,data_offset)
            else:
                tags[tag]=(typ,count,None,data_offset)
    # Extract width, height, strip offset, byte counts, etc
    width=tags.get(256)
    height=tags.get(257)
    if width:
        w=width[2] if isinstance(width[2], int) else width[2][0]
    else:
        w=0
    if height:
        h=height[2] if isinstance(height[2], int) else height[2][0]
    else:
        h=0
    # Strip
    strip_off_tag=tags.get(273)
    strip_bytes_tag=tags.get(279)
    data_bytes=b''
    if strip_off_tag and strip_bytes_tag:
        offs=strip_off_tag[2] if isinstance(strip_off_tag[2], int) else strip_off_tag[2][0] if isinstance(strip_off_tag[2], (list,tuple)) else list(strip_off_tag[2])[0]
        # if multiple strips, need to handle
        if isinstance(strip_off_tag[2], (tuple,list)):
            off_list=strip_off_tag[2]
        else:
            off_list=[strip_off_tag[2]]
        if isinstance(strip_bytes_tag[2], (tuple,list)):
            byte_list=strip_bytes_tag[2]
        else:
            byte_list=[strip_bytes_tag[2]]
        # For simplicity assume single strip
        if len(off_list)==1:
            data_bytes=d[off_list[0]:off_list[0]+byte_list[0]]
    # Geo info
    bbox=None
    crs=None
    if 33550 in tags and 33922 in tags:
        mps=tags[33550][2]  # xres,yres,0
        mtp=tags[33922][2]  # 0,0,0,xmin,ymax,0
        xres=mps[0]
        yres=mps[1]
        xmin=mtp[3]
        ymax=mtp[4]
        xmax=xmin + xres*w
        ymin=ymax - yres*h
        bbox=(xmin,ymin,xmax,ymax)
        # Determine CRS from GeoKeys
        if 34735 in tags:
            gkeys=tags[34735][2]
            # For EPSG:4326 we have key 2048 = 4326, for 3857 key 3072=3857
            # Search for 2048
            # gkeys is tuple of shorts: sequence of 4-tuples
            for j in range(0,len(gkeys),4):
