                if key==2048 and val==4326:
                    crs="EPSG:4326"
                if key==3072 and val==3857:
                    crs="EPSG:3857"
            if crs is None:
                # check if contains 4326
                if 4326 in gkeys:
                    crs="EPSG:4326"
                elif 3857 in gkeys:
                    crs="EPSG:3857"
    return {'width':w,'height':h,'data':data_bytes,'bbox':bbox,'crs':crs,'tags':tags}

