def write_tiff(path, width, height, data=None, bbox=None, crs=None):
    if data is None:
        data = b'\\x00' * (width*height)
    is_geotiff = bbox is not None and crs is not None
    if is_geotiff:
        if crs == "EPSG:4326":
            num_tags = 16
        elif crs == "EPSG:3857":
            num_tags = 15
        else:
            num_tags = 16
    else:
        num_tags = 11
    header_size = 8
    ifd_size = 2 + num_tags*12 + 4
    strip_offset = header_size + ifd_size
    cur = strip_offset + len(data)
    buffers = []
    mp_offset = mtp_offset = gkd_offset = dp_offset = ascii_offset = None
    if is_geotiff:
        xmin,ymin,xmax,ymax = bbox
        xres = (xmax - xmin) / width if width!=0 else 0
        yres = (ymax - ymin) / height if height!=0 else 0
        mps = struct.pack('<ddd', xres, yres, 0.0)
        mp_offset = cur
        buffers.append((mp_offset, mps))
        cur += len(mps)
        mtp = struct.pack('<dddddd', 0.0, 0.0, 0.0, xmin, ymax, 0.0)
        mtp_offset = cur
        buffers.append((mtp_offset, mtp))
        cur += len(mtp)
        if crs == "EPSG:4326":
            gkd_vals = (1,1,0,7,1024,0,1,2,1025,0,1,1,2048,0,1,4326,2049,34737,7,0,2054,0,1,9102,2057,34736,1,1,2059,34736,1,0)
            gkd = struct.pack('<'+'H'*len(gkd_vals), *gkd_vals)
            gkd_offset = cur
            buffers.append((gkd_offset, gkd))
            cur += len(gkd)
            dp = struct.pack('<dd', 298.257223563, 6378137.0)
            dp_offset = cur
            buffers.append((dp_offset, dp))
            cur += len(dp)
            ascii_str = b'WGS 84|\\x00'
            ascii_offset = cur
            buffers.append((ascii_offset, ascii_str))
            cur += len(ascii_str)
        elif crs == "EPSG:3857":
            gkd_vals = (1,1,0,7,1024,0,1,1,1025,0,1,1,1026,34737,25,0,2049,34737,7,25,2054,0,1,9102,3072,0,1,3857,3076,0,1,9001)
            gkd = struct.pack('<'+'H'*len(gkd_vals), *gkd_vals)
            gkd_offset = cur
            buffers.append((gkd_offset, gkd))
            cur += len(gkd)
            ascii_str = b'WGS 84 / Pseudo-Mercator|WGS 84|\\x00'
            ascii_offset = cur
            buffers.append((ascii_offset, ascii_str))
            cur += len(ascii_str)
        else:
            gkd_vals = (1,1,0,7,1024,0,1,2,1025,0,1,1,2048,0,1,4326,2049,34737,7,0,2054,0,1,9102,2057,34736,1,1,2059,34736,1,0)
            gkd = struct.pack('<'+'H'*len(gkd_vals), *gkd_vals)
            gkd_offset = cur
            buffers.append((gkd_offset, gkd))
            cur += len(gkd)
            dp = struct.pack('<dd', 298.257223563, 6378137.0)
            dp_offset = cur
            buffers.append((dp_offset, dp))
            cur += len(dp)
            ascii_str = b'WGS 84|\\x00'
            ascii_offset = cur
            buffers.append((ascii_offset, ascii_str))
            cur += len(ascii_str)
    with open(path,'wb') as f:
        f.write(b'II*\\x00\\x08\\x00\\x00\\x00')
        f.write(struct.pack('<H', num_tags))
        def we(tag, typ, count, val):
            f.write(struct.pack('<HHI', tag, typ, count))
            f.write(struct.pack('<I', val))
        we(256,3,1,width)
        we(257,3,1,height)
        we(258,3,1,8)
        we(259,3,1,1)
        we(262,3,1,1)
        we(273,4,1,strip_offset)
        we(277,3,1,1)
        we(278,3,1,height)
        we(279,4,1,len(data))
        we(284,3,1,1)
        we(339,3,1,1)
        if is_geotiff:
            we(33550,12,3,mp_offset)
            we(33922,12,6,mtp_offset)
            if crs=="EPSG:4326":
                we(34735,3,32,gkd_offset)
                we(34736,12,2,dp_offset)
                we(34737,2,8,ascii_offset)
            elif crs=="EPSG:3857":
                we(34735,3,32,gkd_offset)
                we(34737,2,33,ascii_offset)
            else:
                we(34735,3,32,gkd_offset)
                we(34736,12,2,dp_offset)
                we(34737,2,8,ascii_offset)
        f.write(struct.pack('<I',0))
        f.write(data)
        for off,buf in buffers:
            pos=f.tell()
            if pos<off:
                f.write(b'\\x00'*(off-pos))
            elif pos>off:
                f.seek(off)
            f.write(buf)

def read_tiff(path):
    with open(path,'rb') as f:
        d=f.read()
    if len(d)<8:
        raise Exception("not tiff")
    fmt='<'
    if d[0:2]==b'II':
        fmt='<'
    else:
        fmt='>'
    magic=struct.unpack(fmt+'H', d[2:4])[0]
    if magic!=42:
        raise Exception("not tiff magic")
    off=struct.unpack(fmt+'I', d[4:8])[0]
    num=struct.unpack(fmt+'H', d[off:off+2])[0]
    tags={}
    for i in range(num):
        pos=off+2+i*12
        if pos+12>len(d):
            break
        tag,typ,count,val=struct.unpack(fmt+'HHI4s', d[pos:pos+12])
        val_int=struct.unpack(fmt+'I', val)[0]
        if typ==3 and count==1:
            actual=val_int & 0xFFFF
            tags[tag]=(typ,count,actual,None)
        elif typ==4 and count==1:
            tags[tag]=(typ,count,val_int,None)
        else:
            data_offset=val_int
            if data_offset>=len(d):
                tags[tag]=(typ,count,None,data_offset)
                continue
            if typ==3:
                try:
                    vals=struct.unpack(fmt+f'{count}H', d[data_offset:data_offset+count*2])
                except:
                    vals=()
                tags[tag]=(typ,count,vals,data_offset)
            elif typ==4:
                try:
                    vals=struct.unpack(fmt+f'{count}I', d[data_offset:data_offset+count*4])
                except:
                    vals=()
                tags[tag]=(typ,count,vals,data_offset)
            elif typ==12:
                try:
                    vals=struct.unpack(fmt+f'{count}d', d[data_offset:data_offset+count*8])
                except:
                    vals=()
                tags[tag]=(typ,count,vals,data_offset)
            elif typ==2:
                s=d[data_offset:data_offset+count]
                tags[tag]=(typ,count,s,data_offset)
            else:
                tags[tag]=(typ,count,None,data_offset)
    def get_tag(tag):
        v=tags.get(tag)
        if not v:
            return None
        typ,count,actual,_=v
        if isinstance(actual, int):
            return actual
        if isinstance(actual, (tuple,list)):
            if count==1:
                return actual[0]
            return actual
        return actual
    w=get_tag(256) or 0
    h=get_tag(257) or 0
    strip_off=tags.get(273)
    strip_bytes=tags.get(279)
    data_bytes=b''
    if strip_off and strip_bytes:
        offs=strip_off[2]
        bytes_cnt=strip_bytes[2]
        if isinstance(offs, int):
            off_list=[offs]
        else:
            off_list=list(offs)
        if isinstance(bytes_cnt, int):
            byte_list=[bytes_cnt]
        else:
            byte_list=list(bytes_cnt)
        total=b''
        for o,bc in zip(off_list, byte_list):
            total+=d[o:o+bc]
        data_bytes=total
    bbox=None
    crs=None
    if 33550 in tags and 33922 in tags:
        mps=tags[33550][2]
        mtp=tags[33922][2]
        if isinstance(mps, (tuple,list)) and len(mps)>=2 and isinstance(mtp, (tuple,list)) and len(mtp)>=6:
            xres=mps[0]
            yres=mps[1]
            xmin=mtp[3]
            ymax=mtp[4]
            xmax=xmin + xres*w
            ymin=ymax - yres*h
            bbox=(xmin,ymin,xmax,ymax)
        if 34735 in tags:
            gkeys=tags[34735][2]
            if gkeys:
                for j in range(0,len(gkeys),4):
                    try:
                        key,loc,cnt,val = gkeys[j:j+4]
                    except:
                        continue
                    if key==2048 and val==4326:
                        crs="EPSG:4326"
                    if key==3072 and val==3857:
                        crs="EPSG:3857"
                if crs is None:
                    if 4326 in gkeys:
                        crs="EPSG:4326"
                    elif 3857 in gkeys:
                        crs="EPSG:3857"
    return {'width':w,'height':h,'data':data_bytes,'bbox':bbox,'crs':crs,'tags':tags}

def mercator_forward(lon, lat):
    x = lon * 20037508.34 / 180.0
    lat = max(min(lat, 85.05112878), -85.05112878)
    y = math.log(math.tan((90+lat)*math.pi/360.0)) * 20037508.34 / math.pi
    return x,y

def mercator_inverse(x,y):
    lon = x / 20037508.34 * 180.0
    lat = 180.0 / math.pi * (2*math.atan(math.exp(y/20037508.34*math.pi)) - math.pi/2)
    return lon, lat

def is_raster_file(path):
    try:
        read_tiff(path)
        return True
    except:
        return False

def is_vector_file(path):
    if not os.path.exists(path):
        return False
    if path.endswith('.json') or path.endswith('.geojson'):
        try:
            with open(path,'r') as f:
                j=json.load(f)
            if 'type' in j:
                return True
        except:
            return False
    return False

def driver_from_path(path):
    ext=os.path.splitext(path)[1].lower()
    if ext in ['.tif','.tiff','.vrt']:
        return ('GTiff','GeoTIFF')
    if ext in ['.json','.geojson']:
        return ('GeoJSON','GeoJSON')
    if ext in ['.shp']:
        return ('ESRI Shapefile','ESRI Shapefile')
    if is_raster_file(path):
        return ('GTiff','GeoTIFF')
    if is_vector_file(path):
        return ('GeoJSON','GeoJSON')
    return (None,None)

