        we(256,3,1,width)
        we(257,3,1,height)
        we(258,3,1,8)
        we(259,3,1,1)
        we(262,3,1,1)
        we(273,4,1,strip_offset)
        we(277,3,1,1)
        we(278,3,1,height)
        we(279,4,1,len(data))
        we(284,3,1,1)
        we(339,3,1,1)
        if is_geotiff:
