    try:
        if '%' in size:
            parts=size.split(',')
            w_perc=float(parts[0].strip('%'))
            h_perc=float(parts[1].strip('%'))
            new_w=int(info['width']*w_perc/100)
            new_h=int(info['height']*h_perc/100)
        else:
