    if '--json-usage' in args:
        txt=get_json('vsi_list')
        if txt:
            sys.stdout.write(txt)
        return 0
    fmt="text"
    filename=None
    recursive=False
    i=0
    while i < len(args):
        a=args[i]
        if a in ('-f','--of','--format','--output-format'):
            if i+1<len(args):
                fmt=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--format=') or a.startswith('-f=') or a.startswith('--output-format='):
            fmt=a.split('=',1)[1]
            i+=1
        elif a in ('-R','--recursive'):
            recursive=True
            i+=1
        elif a.startswith('--config'):
            if '=' in a:
                i+=1
            else:
                i+=2
        elif a.startswith('-'):
            if '=' in a:
                i+=1
            else:
                if i+1<len(args) and not args[i+1].startswith('-'):
                    if a in ('--depth',):
                        i+=2
                    else:
                        i+=1
                else:
                    i+=1
        else:
            filename=a
            i+=1
    if filename is None:
        sys.stderr.write("ERROR 1: list: Positional arguments missing\\n")
        return 1
    if not os.path.exists(filename):
        sys.stderr.write(f"ERROR 3: list: '{filename}' does not exist or cannot be accessed\\n")
        return 1
    if os.path.isfile(filename):
        if fmt=="json":
            sys.stdout.write(json.dumps([os.path.basename(filename)]) + "\\n")
        else:
            sys.stdout.write(os.path.basename(filename) + "\\n")
        return 0
    if recursive:
        files=[]
        for root, dirs, filenames in os.walk(filename):
            for fn in filenames:
                rel=os.path.relpath(os.path.join(root, fn), filename)
                files.append(rel)
        files.sort()
    else:
        files=os.listdir(filename)
        files.sort()
    if fmt=="json":
        sys.stdout.write(json.dumps(files))
        sys.stdout.write("\\n")
    else:
        for f in files:
            sys.stdout.write(f + "\\n")
    return 0

