        return 0
    input_file=None
    output_file=None
    overwrite=False
    bbox=None
    quiet=False
    i=0
    while i < len(args):
        a=args[i]
        if a in ('-i','--input'):
            if i+1 < len(args):
                input_file=args[i+1]
                i+=2
            else:
