        return 0
    if '--json-usage' in args:
        txt=get_json('dataset_identify')
        if txt:
            sys.stdout.write(txt)
        return 0
    inputs=[]
    i=0
    while i < len(args):
        a=args[i]
        if a.startswith('-'):
            if '=' in a:
                i+=1
            else:
                if i+1<len(args) and not args[i+1].startswith('-'):
                    i+=2
                else:
                    i+=1
        else:
            inputs.append(a)
            i+=1
    if not inputs:
        sys.stderr.write("ERROR 1: identify: Positional arguments missing\\n")
        return 1
    for inp in inputs:
        if not os.path.exists(inp):
            sys.stderr.write(f"ERROR 4: {inp}: No such file or directory\\n")
            continue
        driver_short,_=driver_from_path(inp)
        if driver_short is None:
