def handle_dataset_copy(args):
    if '-h' in args or '--help' in args:
        txt=get_help('dataset_copy')
        if txt:
            sys.stdout.write(txt)
        else:
            sys.stdout.write("Usage: gdal dataset copy [OPTIONS] <SOURCE> <DESTINATION>\\n")
        return 0
    if '--json-usage' in args:
        txt=get_json('dataset_copy')
        if txt:
            sys.stdout.write(txt)
        return 0
    src=None
    dst=None
    overwrite=False
    i=0
    while i < len(args):
        a=args[i]
        if a=='--overwrite':
            overwrite=True
            i+=1
        elif a in ('--source',):
            if i+1<len(args):
                src=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--source='):
            src=a.split('=',1)[1]
            i+=1
        elif a in ('--destination',):
            if i+1<len(args):
                dst=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--destination='):
            dst=a.split('=',1)[1]
            i+=1
        elif a.startswith('-f') or a.startswith('--format'):
            if '=' in a:
                i+=1
            else:
                i+=2
        elif a.startswith('-'):
            i+=1
        else:
            if src is None:
                src=a
            elif dst is None:
                dst=a
            i+=1
    if src is None or dst is None:
        sys.stderr.write("ERROR 1: copy: Positional arguments missing\\n")
        return 1
    if not os.path.exists(src):
        sys.stderr.write(f"ERROR 4: {src}: No such file or directory\\n")
        return 1
    if os.path.exists(dst) and not overwrite:
        sys.stderr.write(f"ERROR 1: copy: Dataset '{dst}' already exists. Specify the --overwrite option to overwrite it.\\n")
        return 1
    base_src=os.path.splitext(src)[0]
    base_dst=os.path.splitext(dst)[0]
    if src.lower().endswith('.shp'):
        for ext in ['.shp','.shx','.dbf','.prj','.cpg']:
            sf=base_src+ext
            df=base_dst+ext
            if os.path.exists(sf):
                shutil.copyfile(sf, df)
    else:
        shutil.copyfile(src, dst)
    return 0

