    if new_h<=0: new_h=1
    old_data=info['data']
    if len(old_data)<orig_w*orig_h:
        old_data=old_data + b'\x00'*(orig_w*orig_h - len(old_data))
    new_data=bytearray(new_w*new_h)
    for y in range(new_h):
        for x in range(new_w):
