                i+=2
            else:
                i+=1
        elif a.startswith('--output='):
            output_file=a.split('=',1)[1]
            i+=1
        elif a=='--sql':
            if i+1<len(args):
                sql=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--sql='):
            sql=a.split('=',1)[1]
            i+=1
        elif a=='--overwrite':
            overwrite=True
            i+=1
        elif a in ('-q','--quiet'):
            quiet=True
            i+=1
        elif a.startswith('--config'):
            if '=' in a:
                i+=1
            else:
                i+=2
        elif a.startswith('-'):
            if '=' in a:
                i+=1
            else:
                if i+1<len(args) and not args[i+1].startswith('-'):
                    i+=2
                else:
                    i+=1
        else:
            if input_file is None:
                input_file=a
            elif output_file is None:
                output_file=a
            i+=1
    if input_file is None or sql is None:
        sys.stderr.write("ERROR 1: sql: Positional args missing or sql missing\\n")
        return 1
