    dst=None
    overwrite=False
    i=0
    while i < len(args):
        a=args[i]
        if a=='--overwrite':
            overwrite=True
            i+=1
        elif a in ('--source',):
            if i+1<len(args):
                src=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--source='):
            src=a.split('=',1)[1]
            i+=1
        elif a in ('--destination',):
            if i+1<len(args):
