    if '--json-usage' in args:
        txt=get_json('convert')
        if txt:
            sys.stdout.write(txt)
        else:
            sys.stdout.write('{"name":"convert"}')
        return 0
    input_file=None
    output_file=None
    overwrite=False
    quiet=False
    i=0
    while i < len(args):
        a=args[i]
        if a in ('-i','--input'):
            if i+1<len(args):
                input_file=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--input='):
            input_file=a.split('=',1)[1]
            i+=1
        elif a in ('-o','--output'):
            if i+1<len(args):
                output_file=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--output='):
            output_file=a.split('=',1)[1]
            i+=1
        elif a=='--overwrite':
            overwrite=True
            i+=1
        elif a in ('-q','--quiet'):
            quiet=True
            i+=1
        elif a.startswith('--config'):
            if '=' in a:
                i+=1
            else:
                i+=2
        elif a.startswith('-'):
            if '=' in a:
                i+=1
            else:
                if i+1<len(args) and not args[i+1].startswith('-'):
                    i+=2
                else:
                    i+=1
        else:
            if input_file is None:
                input_file=a
            elif output_file is None:
                output_file=a
            i+=1
    if input_file is None or output_file is None:
        sys.stderr.write("ERROR 1: convert: Positional arguments missing\\n")
        return 1
    if not os.path.exists(input_file):
        sys.stderr.write(f"ERROR 4: {input_file}: No such file or directory\\n")
        return 1
    if os.path.exists(output_file) and not overwrite:
        sys.stderr.write(f"ERROR 1: convert: Dataset '{output_file}' already exists. You may specify the --overwrite/--append option.\\n")
        return 1
    if input_file==output_file:
        sys.stderr.write("ERROR 1: Source and destination datasets must be different.\\n")
        return 1
    if is_raster_file(input_file):
        return handle_raster_convert([input_file, output_file] + (['--overwrite'] if overwrite else []) + (['--quiet'] if quiet else []))
    elif is_vector_file(input_file):
        return handle_vector_convert([input_file, output_file] + (['--overwrite'] if overwrite else []) + (['--quiet'] if quiet else []))
    else:
        if input_file.endswith('.tif') or input_file.endswith('.tiff'):
            return handle_raster_convert([input_file, output_file] + (['--overwrite'] if overwrite else []))
        else:
            return handle_vector_convert([input_file, output_file] + (['--overwrite'] if overwrite else []))

