                    f.write(struct.pack('<i', 1))
                    if points:
                        xs=[p[0] for p in points]; ys=[p[1] for p in points]
                        f.write(struct.pack('<4d', min(xs), min(ys), max(xs), max(ys)))
                    else:
                        f.write(struct.pack('<4d', 0,0,0,0))
                    f.write(struct.pack('<4d', 0,0,0,0))
                    for idx,(x,y,props) in enumerate(points, start=1):
                        f.write(struct.pack('>i', idx))
                        f.write(struct.pack('>i', 10))
                        f.write(struct.pack('<i', 1))
                        f.write(struct.pack('<2d', x, y))
                with open(shx_path,'wb') as f:
                    f.write(struct.pack('>i', 9994))
                    f.write(struct.pack('>5i', 0,0,0,0,0))
                    f.write(struct.pack('>i', 50+num_records*4))
                    f.write(struct.pack('<i', 1000))
                    f.write(struct.pack('<i', 1))
                    if points:
                        xs=[p[0] for p in points]; ys=[p[1] for p in points]
                        f.write(struct.pack('<4d', min(xs), min(ys), max(xs), max(ys)))
                    else:
                        f.write(struct.pack('<4d', 0,0,0,0))
                    f.write(struct.pack('<4d', 0,0,0,0))
                    for idx in range(num_records):
                        offset=50+idx*14
                        f.write(struct.pack('>i', offset))
                        f.write(struct.pack('>i', 10))
                import datetime
                now=datetime.datetime.now()
                with open(dbf_path,'wb') as f:
                    f.write(struct.pack('B', 3))
                    f.write(struct.pack('BBB', now.year-1900, now.month, now.day))
                    f.write(struct.pack('<I', num_records))
                    num_fields=1
                    header_size=32+num_fields*32+1
                    record_size=1+10
                    f.write(struct.pack('<H', header_size))
                    f.write(struct.pack('<H', record_size))
                    f.write(b'\\x00'*20)
                    field_name=b'id\\x00\\x00\\x00\\x00\\x00\\x00\\x00\\x00\\x00'
                    field_type=b'N'
                    field_len=10
                    field_dec=0
                    f.write(field_name)
                    f.write(field_type)
                    f.write(struct.pack('<I', 0))
                    f.write(struct.pack('B', field_len))
                    f.write(struct.pack('B', field_dec))
                    f.write(b'\\x00'*14)
                    f.write(b'\\x0D')
                    for (x,y,props) in points:
                        f.write(b' ')
                        id_val=props.get('id',0)
                        f.write(f"{id_val:>10}".encode()[:10])
                    f.write(b'\\x1A')
                with open(prj_path,'w') as f:
                    f.write('GEOGCS["WGS 84",DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563,AUTHORITY["EPSG","7030"]],AUTHORITY["EPSG","6326"]],PRIMEM["Greenwich",0,AUTHORITY["EPSG","8901"]],UNIT["degree",0.0174532925199433,AUTHORITY["EPSG","9122"]],AUTHORITY["EPSG","4326"]]')
            write_shapefile(output_file, data)
        except Exception as e:
