                    i+=2
                else:
                    i+=1
        else:
            if input_file is None:
                input_file=a
            elif output_file is None:
                output_file=a
            i+=1
    if input_file is None or output_file is None:
        sys.stderr.write("ERROR 1: reproject: Positional arguments starting at 'INPUT' have not been specified.\\n")
        return 1
