        sys.stderr.write(f"ERROR 1: copy: Dataset '{dst}' already exists. Specify the --overwrite option to overwrite it.\\n")
        return 1
    base_src=os.path.splitext(src)[0]
    base_dst=os.path.splitext(dst)[0]
    if src.lower().endswith('.shp'):
        for ext in ['.shp','.shx','.dbf','.prj','.cpg']:
            sf=base_src+ext
            df=base_dst+ext
            if os.path.exists(sf):
                shutil.copyfile(sf, df)
