            sys.stdout.write(txt)
        return 0
    src=None
    dst=None
    overwrite=False
    i=0
    while i < len(args):
        a=args[i]
        if a=='--overwrite':
            overwrite=True
            i+=1
        elif a in ('--source',):
            if i+1<len(args):
                src=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--source='):
            src=a.split('=',1)[1]
            i+=1
        elif a in ('--destination',):
            if i+1<len(args):
                dst=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--destination='):
            dst=a.split('=',1)[1]
            i+=1
        elif a.startswith('-f') or a.startswith('--format'):
            if '=' in a:
                i+=1
            else:
                i+=2
        elif a.startswith('-'):
            i+=1
        else:
            if src is None:
                src=a
            elif dst is None:
                dst=a
            i+=1
    if src is None or dst is None:
        sys.stderr.write("ERROR 1: copy: Positional arguments missing\n")
