def handle_pipeline(args):
    if '-h' in args or '--help' in args:
        txt=get_help('pipeline')
        if txt:
            sys.stdout.write(txt)
        else:
            sys.stdout.write("Usage: gdal pipeline [OPTIONS] <PIPELINE>\n")
        return 0
    if '--json-usage' in args:
        txt=get_json('pipeline')
        if txt:
            sys.stdout.write(txt)
        else:
            sys.stdout.write('{"name":"pipeline"}')
        return 0
    quiet=False
    if '-q' in args or '--quiet' in args:
        quiet=True
    filtered=[]
    i=0
    while i < len(args):
        a=args[i]
        if a in ('-q','--quiet'):
            i+=1
        elif a.startswith('--config'):
            if '=' in a:
                i+=1
            else:
                i+=2
        else:
            filtered.append(a)
            i+=1
    pipeline_str=" ".join(filtered)
    steps=[s.strip() for s in pipeline_str.split('!')]
    parsed=[]
    for step_str in steps:
        if not step_str:
            continue
        parts=step_str.split()
        if not parts:
            continue
        parsed.append((parts[0], parts[1:]))
    if not parsed:
        sys.stderr.write("ERROR 1: pipeline: No steps specified\n")
        return 1
    first_name, first_args = parsed[0]
    if first_name not in ('read','calc','concat','create','mosaic','stack'):
        if first_name!='read':
            sys.stderr.write(f"ERROR 1: pipeline: First step must be one of read, calc, concat, create, mosaic, stack, but got '{first_name}'\n")
            return 1
    current_raster=None
    current_raster_path=None
    current_vector=None
    current_vector_path=None
    current_is_raster=None
    name, sargs = parsed[0]
    if name=='read':
        input_file=None
        i=0
        while i < len(sargs):
            a=sargs[i]
            if a.startswith('-'):
                if '=' in a:
                    i+=1
                else:
                    if i+1<len(sargs) and not sargs[i+1].startswith('-'):
                        i+=2
                    else:
                        i+=1
            else:
                input_file=a
                i+=1
        if input_file is None:
            sys.stderr.write("ERROR 1: read: Input missing\n")
            return 1
        if not os.path.exists(input_file):
            sys.stderr.write(f"ERROR 4: {input_file}: No such file or directory\n")
            return 1
        if is_raster_file(input_file):
            try:
                current_raster=read_tiff(input_file)
                current_raster_path=input_file
                current_is_raster=True
            except:
                sys.stderr.write(f"ERROR 4: `{input_file}' not recognized as being in a supported file format.\n")
                return 1
        elif is_vector_file(input_file):
            try:
                with open(input_file,'r') as f:
                    current_vector=json.load(f)
                current_vector_path=input_file
                current_is_raster=False
            except:
                sys.stderr.write(f"ERROR 4: `{input_file}' not recognized as being in a supported file format.\n")
                return 1
        else:
            try:
                current_raster=read_tiff(input_file)
                current_raster_path=input_file
                current_is_raster=True
            except:
                try:
                    with open(input_file,'r') as f:
                        current_vector=json.load(f)
                    current_vector_path=input_file
                    current_is_raster=False
                except:
                    sys.stderr.write(f"ERROR 4: `{input_file}' not recognized as being in a supported file format.\n")
                    return 1
    elif name=='calc':
        inputs=[]
        i=0
        while i < len(sargs):
            a=sargs[i]
            if a.startswith('-'):
                if '=' in a:
                    i+=1
                else:
                    if i+1<len(sargs) and not sargs[i+1].startswith('-'):
                        i+=2
                    else:
                        i+=1
            else:
                inputs.append(a)
                i+=1
        if not inputs:
            sys.stderr.write("ERROR 1: calc: No inputs\n")
            return 1
        try:
            current_raster=read_tiff(inputs[0])
            current_raster_path=inputs[0]
            current_is_raster=True
        except:
            sys.stderr.write("ERROR 1: calc: Failed to open inputs\n")
            return 1
    else:
        sys.stderr.write(f"ERROR 1: pipeline: First step '{name}' not implemented\n")
        return 1
    for name, sargs in parsed[1:]:
        if name=='info':
            fmt="text"
            i=0
            while i < len(sargs):
                a=sargs[i]
