    known_top = ['convert','dataset','driver','info','mdim','pipeline','raster','vector','vsi','read']
    first = argv[0]
    if first not in known_top and not first.startswith('-'):
        if os.path.exists(first):
            argv = ['info', first] + argv[1:]
        elif first == 'read':
            argv = ['pipeline'] + argv
    if not argv:
        print_top_help()
        return 0
    if '--version' in argv:
