        sys.stdout.write(DRIVERS_JSON + "\\n")
        return 0
    temp=[]
    i=0
    while i < len(argv):
        a=argv[i]
        if a.startswith('--config'):
            if '=' in a:
                i+=1
            else:
                i+=2
        else:
            temp.append(a)
            i+=1
    argv=temp
    if not argv:
        print_top_help()
        return 0
    cmd = argv[0]
    rest = argv[1:]
    if cmd == 'raster':
        return handle_raster(rest)
    elif cmd == 'vector':
        return handle_vector(rest)
    elif cmd == 'dataset':
        return handle_dataset(rest)
    elif cmd == 'vsi':
