        txt=get_json('info')
        if txt:
            sys.stdout.write(txt)
        else:
            sys.stdout.write('{"name":"info"}')
        return 0
    input_file=None
    fmt="text"
    i=0
    while i < len(args):
        a=args[i]
        if a in ('-i','--dataset','--input'):
            if i+1<len(args):
                input_file=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--input=') or a.startswith('--dataset='):
            input_file=a.split('=',1)[1]
            i+=1
        elif a in ('-f','--of','--format','--output-format'):
            if i+1<len(args):
                fmt=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--format=') or a.startswith('--output-format='):
            fmt=a.split('=',1)[1]
            i+=1
        elif a.startswith('--config'):
            if '=' in a:
                i+=1
            else:
                i+=2
        elif a.startswith('-'):
            if '=' in a:
                i+=1
            else:
                if i+1<len(args) and not args[i+1].startswith('-'):
                    i+=2
                else:
                    i+=1
        else:
            input_file=a
            i+=1
    if input_file is None:
        sys.stderr.write("ERROR 1: info: Positional arguments starting at 'INPUT' have not been specified.\\nUsage: gdal info [OPTIONS] <INPUT>\\nTry 'gdal info --help' for help.\\n")
        return 1
    if not os.path.exists(input_file):
        sys.stderr.write(f"ERROR 4: {input_file}: No such file or directory\\nUsage: gdal info [OPTIONS] <INPUT>\\nTry 'gdal info --help' for help.\\n")
