def handle_raster(args):
    if not args:
        txt=get_help('raster')
        if txt:
            sys.stdout.write(txt)
        else:
            sys.stdout.write("Usage: gdal raster <SUBCOMMAND> [OPTIONS]\\n")
        return 0
    sub=args[0]
    rest=args[1:]
    if sub == '--drivers':
        if os.environ.get('GDAL_DATA') is None:
            sys.stderr.write(WARNING_TMS + "\\n")
        sys.stdout.write(RASTER_DRIVERS_JSON + "\\n")
        return 0
    if sub in ('-h','--help'):
        txt=get_help('raster')
        if txt:
            sys.stdout.write(txt)
        return 0
    if sub == '--json-usage':
        txt=get_json('raster')
        if txt:
            sys.stdout.write(txt)
        return 0
    # Generic dispatcher for raster subcommands via HELPS
    # If subcommand exists, try specific handlers
    if sub == 'info':
        return handle_raster_info(rest)
    elif sub == 'convert':
        return handle_raster_convert(rest)
    elif sub == 'create':
        return handle_raster_create(rest)
    elif sub == 'resize':
        return handle_raster_resize(rest)
    elif sub == 'clip':
        return handle_raster_clip(rest)
    elif sub == 'reproject':
        return handle_raster_reproject(rest)
    elif sub == 'calc':
        return handle_raster_calc(rest)
    elif sub == 'mosaic':
        return handle_raster_mosaic(rest)
    elif sub == 'stack':
        return handle_raster_stack(rest)
    elif sub == 'overview':
        return handle_raster_overview(rest)
    elif sub == 'tile':
        return handle_raster_tile(rest)
    elif sub == 'pipeline':
        return handle_pipeline(rest)
    else:
        key=f"raster_{sub}"
        txt=get_help(key)
        if txt and ('--help' in rest or '-h' in rest):
            sys.stdout.write(txt)
            return 0
        if txt and '--json-usage' in rest:
            jtxt=get_json(key)
            if jtxt:
                sys.stdout.write(jtxt)
            return 0
        if get_help(key) is not None:
            # Check if it's a generic raster command that should succeed by copying
            # For many raster commands, original succeeds with just input/output
            # We'll attempt generic copy
            return handle_generic_raster_command(sub, rest)
        sys.stderr.write(f"ERROR 1: raster: Unknown command: '{sub}'\\n")
        txt_generic=get_help('raster')
        if txt_generic:
            sys.stderr.write(txt_generic)
        return 1

