def handle_generic_raster_command(cmd_name, args):
    if '-h' in args or '--help' in args:
        txt=get_help(f'raster_{cmd_name}')
        if txt:
            sys.stdout.write(txt)
        else:
            sys.stdout.write(f"Usage: gdal raster {cmd_name} [OPTIONS] <INPUT> <OUTPUT>\\n")
        return 0
    if '--json-usage' in args:
        txt=get_json(f'raster_{cmd_name}')
        if txt:
            sys.stdout.write(txt)
        else:
