    if '-h' in args or '--help' in args:
        txt=get_help('dataset_rename')
        if txt:
            sys.stdout.write(txt)
        else:
            sys.stdout.write("Usage: gdal dataset rename [OPTIONS] <SOURCE> <DESTINATION>\\n")
        return 0
    src=None
    dst=None
    overwrite=False
    i=0
    while i < len(args):
        a=args[i]
        if a=='--overwrite':
            overwrite=True
            i+=1
        elif a in ('--source',):
            if i+1<len(args):
                src=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--source='):
            src=a.split('=',1)[1]
            i+=1
        elif a in ('--destination',):
            if i+1<len(args):
                dst=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--destination='):
            dst=a.split('=',1)[1]
            i+=1
        elif a.startswith('-'):
            if '=' in a:
                i+=1
            else:
                if i+1<len(args) and not args[i+1].startswith('-'):
                    i+=2
                else:
                    i+=1
        else:
            if src is None:
                src=a
            elif dst is None:
                dst=a
            i+=1
    if src is None or dst is None:
        sys.stderr.write("ERROR 1: rename: Positional args missing\\n")
        return 1
    if not os.path.exists(src):
        sys.stderr.write(f"ERROR 4: {src}: No such file or directory\\n")
        return 1
    if os.path.exists(dst) and not overwrite:
        sys.stderr.write(f"ERROR 1: rename: Dataset '{dst}' already exists.\\n")
        return 1
    shutil.move(src, dst)
    return 0

