    def transform_coords(coords, src="EPSG:4326", dst=dst_crs):
        if isinstance(coords[0], (int,float)):
            x,y=coords[0],coords[1]
            if src=="EPSG:4326" and dst=="EPSG:3857":
                return list(mercator_forward(x,y))
            elif src=="EPSG:3857" and dst=="EPSG:4326":
                return list(mercator_inverse(x,y))
            else:
                return coords
        else:
            return [transform_coords(c, src, dst) for c in coords]
    for ftr in data.get('features',[]):
