    except:
        sys.stderr.write("ERROR 4: not recognized\\n")
        return 1
    m=re.match(r'\\s*SELECT\\s+(.+)\\s+FROM\\s+(\\w+)', sql, re.IGNORECASE)
    if m:
        fields_str=m.group(1).strip()
        if fields_str!='*':
            fields=[f.strip() for f in fields_str.split(',')]
