                xs=[]; ys=[]
                for ftr in features:
                    geom=ftr.get('geometry',{})
                    coords=geom.get('coordinates')
                    if coords and isinstance(coords[0], (int,float)):
                        xs.append(coords[0]); ys.append(coords[1])
                extent=[min(xs) if xs else 0.0, min(ys) if ys else 0.0, max(xs) if xs else 0.0, max(ys) if ys else 0.0]
                fields=[]
                if features:
                    props=features[0].get('properties',{})
                    for k,v in props.items():
                        ftype="Integer" if isinstance(v, int) else "Real" if isinstance(v, float) else "String"
                        fields.append({"name":k,"type":ftype,"nullable":True,"uniqueConstraint":False})
                layer={"name":layer_name,"metadata":{},"geometryFields":[{"name":"","type":geom_type,"nullable":True,"extent":extent}],"featureCount":len(features),"fidColumnName":"id","fields":fields}
                output={"description":inp,"driverShortName":"GeoJSON","driverLongName":"GeoJSON","layers":[layer],"metadata":{},"domains":{},"relationships":{}}
                sys.stdout.write(json.dumps(output, indent=2, separators=(',', ':')))
                sys.stdout.write("\\n")
            else:
                driver="GeoJSON"
                layer_name=os.path.splitext(os.path.basename(inp))[0]
                sys.stdout.write(f"INFO: Open of `{inp}'\\n      using driver `{driver}' successful.\\n")
                sys.stdout.write(f"\\nLayer name: {layer_name}\\n")
                sys.stdout.write("Geometry: Point\\n")
                features=data.get('features',[])
                sys.stdout.write(f"Feature Count: {len(features)}\\n")
                xs=[]; ys=[]
                for ftr in features:
                    geom=ftr.get('geometry',{})
                    coords=geom.get('coordinates')
                    if coords and isinstance(coords[0], (int,float)):
                        xs.append(coords[0]); ys.append(coords[1])
                if xs:
                    sys.stdout.write(f"Extent: ({min(xs):.6f}, {min(ys):.6f}) - ({max(xs):.6f}, {max(ys):.6f})\\n")
                else:
                    sys.stdout.write("Extent: (0.000000, 0.000000) - (0.000000, 0.000000)\\n")
                sys.stdout.write("Layer Coordinate Reference System:\\n  - name: WGS 84\\n  - ID: EPSG:4326\\n  - type: Geographic 2D\\nData axis to CRS axis mapping: 2,1\\nFID Column = id\\n")
                if features:
                    props=features[0].get('properties',{})
                    for k,v in props.items():
                        if isinstance(v, int):
                            sys.stdout.write(f"{k}: Integer (0.0)\\n")
                        elif isinstance(v, float):
                            sys.stdout.write(f"{k}: Real (0.0)\\n")
                        else:
                            sys.stdout.write(f"{k}: String (0.0)\\n")
        else:
            sys.stderr.write(f"ERROR 4: `{inp}' not recognized as being in a supported file format.\\n")
            return 1
    return 0

