    input_file=None
    output_file=None
    dst_crs=None
    overwrite=False
    quiet=False
    i=0
    while i < len(args):
        a=args[i]
        if a in ('-i','--input'):
            if i+1<len(args):
                input_file=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--input='):
            input_file=a.split('=',1)[1]
            i+=1
        elif a in ('-o','--output'):
