        else:
            if input_file is None:
                input_file=a
            elif output_file is None:
                output_file=a
            i+=1
    if input_file is None or output_file is None:
        sys.stderr.write("ERROR 1: filter: Positional args missing\\n")
        return 1
    if not os.path.exists(input_file):
        sys.stderr.write(f"ERROR 4: {input_file}: No such file or directory\\n")
        return 1
    if os.path.exists(output_file) and not overwrite:
        sys.stderr.write(f"ERROR 1: filter: Dataset exists\\n")
        return 1
    try:
        with open(input_file,'r') as f:
            data=json.load(f)
    except:
        sys.stderr.write("ERROR 4: not recognized\\n")
        return 1
    if where:
        m=re.match(r'\\s*(\\w+)\\s*=\\s*(.+)\\s*', where)
        if m:
            key=m.group(1)
            val_str=m.group(2).strip().strip('\'"')
            try:
                val=int(val_str)
            except:
                try:
                    val=float(val_str)
