        return 0
    input_file=None
    output_file=None
    dst_crs=None
    overwrite=False
    quiet=False
    i=0
    while i < len(args):
        a=args[i]
        if a in ('-i','--input'):
            if i+1<len(args):
                input_file=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--input='):
            input_file=a.split('=',1)[1]
            i+=1
        elif a in ('-o','--output'):
            if i+1<len(args):
                output_file=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--output='):
            output_file=a.split('=',1)[1]
            i+=1
        elif a in ('-d','--dst-crs'):
            if i+1<len(args):
                dst_crs=args[i+1]
                i+=2
            else:
                i+=1
        elif a.startswith('--dst-crs=') or a.startswith('-d='):
            dst_crs=a.split('=',1)[1]
            i+=1
        elif a=='--overwrite':
            overwrite=True
            i+=1
        elif a in ('-q','--quiet'):
            quiet=True
            i+=1
