def write_tiff(path, width, height, data=None, bbox=None, crs=None):
    if data is None:
        data = b"\\x00" * (width*height)
    is_geotiff = bbox is not None and crs is not None
    num_tags = 16 if is_geotiff and crs == "EPSG:4326" else 15 if is_geotiff else 11
