    sys.stdout.write(VERSION_STR + "\\n")

def parse_generic_args(args):
    inputs=[]
    overwrite=False
    quiet=False
    opts={}
    i=0
    while i < len(args):
        a=args[i]
        if a=='--overwrite':
            overwrite=True
            i+=1
        elif a in ('-q','--quiet'):
            quiet=True
            i+=1
        elif a.startswith('--config'):
            if '=' in a:
                i+=1
            else:
                i+=2
        elif a.startswith('--'):
            if '=' in a:
                k,v=a[2:].split('=',1)
                opts[k]=v
                i+=1
            else:
                k=a[2:]
                if i+1 < len(args) and not args[i+1].startswith('-'):
                    opts[k]=args[i+1]
                    i+=2
                else:
                    opts[k]=True
                    i+=1
        elif a.startswith('-'):
            if i+1 < len(args) and not args[i+1].startswith('-'):
                opts[a.lstrip('-')]=args[i+1]
                i+=2
            else:
                opts[a.lstrip('-')]=True
                i+=1
        else:
            inputs.append(a)
            i+=1
    return {'inputs':inputs,'overwrite':overwrite,'quiet':quiet,'opts':opts}
