def mercator_forward(lon, lat):
    import math
    x=lon*20037508.34/180.0
    lat=max(min(lat,85.05112878),-85.05112878)
    y=math.log(math.tan((90+lat)*math.pi/360.0))*20037508.34/math.pi
    return x,y

def mercator_inverse(x,y):
    import math
    lon=x/20037508.34*180.0
    lat=180.0/math.pi*(2*math.atan(math.exp(y/20037508.34*math.pi))-math.pi/2)
    return lon, lat

