        parts=[float(x) for x in bbox.split(',')]
        xmin,ymin,xmax,ymax=parts
    except:
        sys.stderr.write("ERROR 5: Invalid bbox\\n")
        return 1
    orig_xmin,orig_ymin,orig_xmax,orig_ymax=info['bbox']
    orig_w=info['width']; orig_h=info['height']
    orig_xres=(orig_xmax-orig_xmin)/orig_w
    orig_yres=(orig_ymax-orig_ymin)/orig_h
    col=int(round((xmin - orig_xmin)/orig_xres)) if orig_xres!=0 else 0
    row=int(round((orig_ymax - ymax)/orig_yres)) if orig_yres!=0 else 0
    new_w=int(round((xmax - xmin)/orig_xres)) if orig_xres!=0 else orig_w
    new_h=int(round((ymax - ymin)/orig_yres)) if orig_yres!=0 else orig_h
    if new_w<=0: new_w=1
    if new_h<=0: new_h=1
    old_data=info['data']
